from collections import defaultdict

class Solution:
    def maximumSubarraySum(self, nums: list[int], k: int) -> int:
        count = defaultdict(int)
        window_sum = 0
        result = 0
        for i in range(len(nums)):
            count[nums[i]] += 1
            window_sum += nums[i]
            if i >= k:
                count[nums[i - k]] -= 1
                if count[nums[i - k]] == 0:
                    del count[nums[i - k]]
                window_sum -= nums[i - k]
            if i >= k - 1 and len(count) == k:
                result = max(result, window_sum)
        return result

